    /** Adjacent paragraphs in a layout-table cell are separated rather than concatenated into one run of text */
    public function test_table_layout_cell_paragraphs_stay_separated(): void
    {
        $options = \HtmlToMarkdown\ConversionOptions::from_json(json_encode(['compactTables' => true]));
        $result = HtmlToMarkdown::convert(
            '<table><tr><td><p><b>Alice Example</b></p><p><i>Customer Service</i></p></td><td>Logo</td></tr><tr><td>A</td><td>B</td><td>C</td></tr></table>',
            $options,
        );

        $this->assertStringNotContainsString('**Alice Example***Customer Service*', $result->content ?? null);
        $this->assertStringContainsString('Alice Example', $result->content ?? null);
        $this->assertStringContainsString('Customer Service', $result->content ?? null);
        $this->assertStringContainsString('Logo', $result->content ?? null);
    }

